/// <summary>
/// Example UPSPricingAttribute of table <c>RetailInventTable</c> field blockedOnPOS.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeRetailInventTableBlockedOnPos extends UPSPricingAttributeRetailInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(RetailInventTable, blockedOnPOS);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::Enum);
    RetailInventTable retailInventTable;
    while select blockedOnPOS from retailInventTable
        group by blockedOnPOS
    {
        ret.add(retailInventTable.blockedOnPOS);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(RetailInventTable, blockedOnPOS));
    qbr.value(queryValue(_value));
}
